INSERT INTO instructions (id, slug, title, summary, content, is_published, sort_order, created_at, updated_at) VALUES ('ins_account', 'subscription-activation', '{"en":"Activating a subscription on your account","ru":"Активация подписки на вашем аккаунте","zh":"在您的账户上激活订阅"}', '{"en":"How we upgrade your existing ChatGPT, Claude or Grok account.","ru":"Как мы подключаем тариф к вашему аккаунту ChatGPT, Claude или Grok.","zh":"我们如何为您现有的 ChatGPT、Claude 或 Grok 账户升级。"}', '{"en":[{"type":"paragraph","text":"Your subscription is activated on **your own account** — you keep your chats, history and settings."},{"type":"steps","items":[{"title":"Send us your login email","text":"Message support in Telegram with your order ID and the email of the account to upgrade."},{"title":"Confirm the sign-in code","text":"We''ll ask for a one-time code sent to your email. Share it only with official support."},{"title":"Wait for activation","text":"Activation usually takes 5–30 minutes. The order page updates when it''s done."},{"title":"Sign out and back in","text":"Reload the app or sign in again to see the upgraded plan."}]},{"type":"callout","tone":"warning","title":"Keep your account secure","text":"Change your password after activation and never share codes with anyone except our official support."},{"type":"faq","items":[{"question":"Will I lose my chat history?","answer":"No. The plan is applied to your existing account."}]}],"ru":[{"type":"paragraph","text":"Подписка активируется на **вашем аккаунте** — чаты, история и настройки сохраняются."},{"type":"steps","items":[{"title":"Отправьте email аккаунта","text":"Напишите в поддержку в Telegram номер заказа и email аккаунта, который нужно активировать."},{"title":"Подтвердите код входа","text":"Мы попросим одноразовый код из письма. Передавайте его только официальной поддержке."},{"title":"Дождитесь активации","text":"Обычно занимает 5–30 минут. Страница заказа обновится автоматически."},{"title":"Перезайдите в аккаунт","text":"Обновите приложение или войдите заново, чтобы увидеть новый тариф."}]},{"type":"callout","tone":"warning","title":"Безопасность аккаунта","text":"Смените пароль после активации и никому, кроме официальной поддержки, не передавайте коды."},{"type":"faq","items":[{"question":"Сохранится ли история чатов?","answer":"Да. Тариф подключается к вашему текущему аккаунту."}]}],"zh":[{"type":"paragraph","text":"订阅将在**您自己的账户**上激活——聊天记录、历史和设置都会保留。"},{"type":"steps","items":[{"title":"发送登录邮箱","text":"在 Telegram 联系客服，提供订单号和需要升级的账户邮箱。"},{"title":"确认登录验证码","text":"我们会请您提供邮箱中的一次性验证码，请仅提供给官方客服。"},{"title":"等待激活","text":"激活通常需要 5–30 分钟，完成后订单页面会自动更新。"},{"title":"重新登录","text":"刷新应用或重新登录即可看到升级后的套餐。"}]},{"type":"callout","tone":"warning","title":"保护账户安全","text":"激活后请修改密码，除官方客服外不要向任何人提供验证码。"}]}', 1, 0, 1790161415440, 1790161415440);
INSERT INTO instructions (id, slug, title, summary, content, is_published, sort_order, created_at, updated_at) VALUES ('ins_code', 'redeem-a-code', '{"en":"Redeeming a code","ru":"Активация кода","zh":"兑换码使用方法"}', '{"en":"Three steps to redeem promo codes and gift cards.","ru":"Три шага для активации промокодов и подарочных карт.","zh":"三步兑换优惠码和礼品卡。"}', '{"en":[{"type":"steps","items":[{"title":"Copy your code","text":"Your code is shown above in the **Digital delivery** section."},{"title":"Open the redeem page","text":"Sign in to your account and open the redemption page of the service."},{"title":"Paste and confirm","text":"Paste the code and confirm. The benefit is applied instantly."}]},{"type":"callout","tone":"tip","text":"Redeem the code soon after purchase — some codes have an activation deadline."}],"ru":[{"type":"steps","items":[{"title":"Скопируйте код","text":"Код показан выше в разделе **Цифровая выдача**."},{"title":"Откройте страницу активации","text":"Войдите в аккаунт сервиса и откройте страницу активации кода."},{"title":"Вставьте и подтвердите","text":"Вставьте код и подтвердите. Бонус начислится сразу."}]},{"type":"callout","tone":"tip","text":"Активируйте код вскоре после покупки — у некоторых кодов есть срок активации."}],"zh":[{"type":"steps","items":[{"title":"复制兑换码","text":"兑换码显示在上方的**数字交付**区域。"},{"title":"打开兑换页面","text":"登录服务账户并打开兑换页面。"},{"title":"粘贴并确认","text":"粘贴兑换码并确认，权益立即生效。"}]},{"type":"callout","tone":"tip","text":"请在购买后尽快兑换——部分兑换码有激活期限。"}]}', 1, 1, 1790161415440, 1790161415440);
INSERT INTO instructions (id, slug, title, summary, content, is_published, sort_order, created_at, updated_at) VALUES ('ins_windows', 'windows-activation', '{"en":"Activating Windows","ru":"Активация Windows","zh":"激活 Windows"}', '{"en":"Enter a product key in Settings or from the terminal.","ru":"Ввод ключа через параметры или терминал.","zh":"在设置或终端中输入产品密钥。"}', '{"en":[{"type":"steps","items":[{"title":"Open Settings","text":"Go to **Settings → System → Activation**."},{"title":"Change product key","text":"Click **Change product key** and paste the key from your order."},{"title":"Or use the command line","text":"Run the command below in an elevated terminal."}]},{"type":"code","language":"powershell","code":"slmgr /ipk XXXXX-XXXXX-XXXXX-XXXXX-XXXXX\nslmgr /ato"},{"type":"link","label":"Microsoft activation help","url":"https://support.microsoft.com/windows/activate-windows"}],"ru":[{"type":"steps","items":[{"title":"Откройте параметры","text":"Перейдите в **Параметры → Система → Активация**."},{"title":"Измените ключ продукта","text":"Нажмите **Изменить ключ продукта** и вставьте ключ из заказа."},{"title":"Или через командную строку","text":"Выполните команду ниже в терминале от имени администратора."}]},{"type":"code","language":"powershell","code":"slmgr /ipk XXXXX-XXXXX-XXXXX-XXXXX-XXXXX\nslmgr /ato"},{"type":"link","label":"Справка Microsoft по активации","url":"https://support.microsoft.com/windows/activate-windows"}]}', 1, 2, 1790161415440, 1790161415440);
INSERT INTO products (id, slug, category_id, instruction_id, name, short_description, description, thumbnail_url, accent, price, old_price, currency, stock, unlimited_stock, min_quantity, max_quantity, is_active, is_featured, is_popular, sort_priority, delivery_type, delivery_time, static_delivery, warranty, requirements, region_restrictions, tags, seo_title, seo_description, faq, quantity_discounts, created_at, updated_at) VALUES ('prod_chatgpt_plus', 'chatgpt-plus', 'cat_ai', 'ins_account', '{"en":"ChatGPT Plus","ru":"ChatGPT Plus","zh":"ChatGPT Plus"}', '{"en":"GPT access with higher limits, advanced voice, image generation and file analysis.","ru":"Доступ к GPT с повышенными лимитами, голосовым режимом, генерацией изображений и анализом файлов.","zh":"更高额度的 GPT 使用权限，支持高级语音、图像生成和文件分析。"}', '{"en":"Upgrade your own OpenAI account to **ChatGPT Plus**.\n\n## What''s included\n- Higher message limits on the latest models\n- Advanced voice mode\n- Image generation and file uploads\n- Custom GPTs and projects\n\nActivation is done on your existing account, so your chats and settings stay intact.","ru":"Подключение **ChatGPT Plus** к вашему аккаунту OpenAI.\n\n## Что входит\n- Повышенные лимиты на новейших моделях\n- Продвинутый голосовой режим\n- Генерация изображений и загрузка файлов\n- Собственные GPT и проекты\n\nАктивация выполняется на вашем аккаунте — чаты и настройки сохраняются.","zh":"为您自己的 OpenAI 账户升级 **ChatGPT Plus**。\n\n## 包含内容\n- 最新模型更高的消息额度\n- 高级语音模式\n- 图像生成和文件上传\n- 自定义 GPT 与项目\n\n在您现有账户上激活，聊天记录和设置均保留。"}', NULL, '#10a37f', 2200, 2500, 'USD', 0, 1, 1, 3, 1, 1, 1, 100, 'manual', '{"en":"Within 5–30 minutes","ru":"В течение 5–30 минут","zh":"5–30 分钟内"}', NULL, '{"en":"Full warranty for the entire subscription period","ru":"Гарантия на весь срок подписки","zh":"整个订阅期内全程保修"}', '{"en":"- An OpenAI account you can sign in to\n- Access to the account''s email for a one-time code","ru":"- Аккаунт OpenAI, в который вы можете войти\n- Доступ к почте аккаунта для одноразового кода","zh":"- 可以登录的 OpenAI 账户\n- 可接收一次性验证码的账户邮箱"}', '{}', 'chatgpt, openai, gpt, ai', '{}', '{}', '[{"question":{"en":"Is it activated on my account?","ru":"Активация на моём аккаунте?","zh":"是在我的账户上激活吗？"},"answer":{"en":"Yes — we upgrade your existing account.","ru":"Да — мы подключаем тариф к вашему текущему аккаунту.","zh":"是的——我们为您现有的账户升级。"}}]', '[]', 1790161415440, 1790161415440);
