INSERT INTO products (id, slug, category_id, instruction_id, name, short_description, description, thumbnail_url, accent, price, old_price, currency, stock, unlimited_stock, min_quantity, max_quantity, is_active, is_featured, is_popular, sort_priority, delivery_type, delivery_time, static_delivery, warranty, requirements, region_restrictions, tags, seo_title, seo_description, faq, quantity_discounts, created_at, updated_at) VALUES ('prod_claude_pro', 'claude-pro', 'cat_ai', 'ins_account', '{"en":"Claude Pro","ru":"Claude Pro","zh":"Claude Pro"}', '{"en":"More usage, projects and priority access to the latest Claude models.","ru":"Больше лимитов, проекты и приоритетный доступ к новейшим моделям Claude.","zh":"更多用量、项目功能以及对最新 Claude 模型的优先访问。"}', '{"en":"Upgrade your Claude account to **Pro** for more usage, Projects and priority access during peak times.","ru":"Подключите **Claude Pro**: больше лимитов, Проекты и приоритетный доступ в часы нагрузки.","zh":"将您的 Claude 账户升级到 **Pro**，获得更多用量、项目功能以及高峰时段的优先访问。"}', NULL, '#d97757', 2100, NULL, 'USD', 0, 1, 1, 3, 1, 1, 1, 90, 'manual', '{"en":"Within 5–30 minutes","ru":"В течение 5–30 минут","zh":"5–30 分钟内"}', NULL, '{"en":"Full warranty for the entire subscription period","ru":"Гарантия на весь срок подписки","zh":"整个订阅期内全程保修"}', '{"en":"- A Claude account\n- Access to the account''s email","ru":"- Аккаунт Claude\n- Доступ к почте аккаунта","zh":"- Claude 账户\n- 可访问账户邮箱"}', '{}', 'claude, anthropic, ai', '{}', '{}', '[]', '[]', 1790161415440, 1790161415440);
