INSERT INTO products (id, slug, category_id, instruction_id, name, short_description, description, thumbnail_url, accent, price, old_price, currency, stock, unlimited_stock, min_quantity, max_quantity, is_active, is_featured, is_popular, sort_priority, delivery_type, delivery_time, static_delivery, warranty, requirements, region_restrictions, tags, seo_title, seo_description, faq, quantity_discounts, created_at, updated_at) VALUES ('prod_perplexity_pro', 'perplexity-pro', 'cat_ai', 'ins_code', '{"en":"Perplexity Pro — 12 months","ru":"Perplexity Pro — 12 месяцев","zh":"Perplexity Pro — 12 个月"}', '{"en":"A promo code for a full year of Perplexity Pro. Delivered instantly.","ru":"Промокод на год Perplexity Pro. Мгновенная выдача.","zh":"Perplexity Pro 全年兑换码，即时交付。"}', '{"en":"A **promo code** for 12 months of Perplexity Pro: Pro searches, file analysis and access to top models.\n\nRedeem it on a new or existing account.","ru":"**Промокод** на 12 месяцев Perplexity Pro: Pro-поиск, анализ файлов и доступ к топовым моделям.\n\nАктивируется на новом или существующем аккаунте.","zh":"Perplexity Pro 12 个月**兑换码**：Pro 搜索、文件分析及顶级模型访问。\n\n可在新账户或现有账户上兑换。"}', NULL, '#20b8cd', 2900, 20000, 'USD', 0, 0, 1, 10, 1, 1, 0, 80, 'inventory', '{"en":"Instantly after payment","ru":"Сразу после оплаты","zh":"付款后立即"}', NULL, '{"en":"Full warranty for the entire subscription period","ru":"Гарантия на весь срок подписки","zh":"整个订阅期内全程保修"}', '{"en":"- A Perplexity account without an active subscription","ru":"- Аккаунт Perplexity без активной подписки","zh":"- 没有有效订阅的 Perplexity 账户"}', '{}', 'perplexity, search, ai', '{}', '{}', '[]', '[]', 1790161415440, 1790161415440);
