INSERT INTO products (id, slug, category_id, instruction_id, name, short_description, description, thumbnail_url, accent, price, old_price, currency, stock, unlimited_stock, min_quantity, max_quantity, is_active, is_featured, is_popular, sort_priority, delivery_type, delivery_time, static_delivery, warranty, requirements, region_restrictions, tags, seo_title, seo_description, faq, quantity_discounts, created_at, updated_at) VALUES ('prod_supergrok', 'supergrok', 'cat_ai', 'ins_account', '{"en":"SuperGrok","ru":"SuperGrok","zh":"SuperGrok"}', '{"en":"Grok with higher limits, DeepSearch and extended reasoning.","ru":"Grok с увеличенными лимитами, DeepSearch и расширенными рассуждениями.","zh":"更高额度的 Grok，支持 DeepSearch 和扩展推理。"}', '{"en":"Upgrade your xAI account to **SuperGrok** for higher usage limits and advanced features.","ru":"Подключите **SuperGrok** к аккаунту xAI: увеличенные лимиты и расширенные функции.","zh":"将您的 xAI 账户升级到 **SuperGrok**，获得更高用量和高级功能。"}', NULL, '#8b8b8b', 2700, 3000, 'USD', 0, 1, 1, 3, 1, 1, 0, 70, 'manual', '{"en":"Within 5–30 minutes","ru":"В течение 5–30 минут","zh":"5–30 分钟内"}', NULL, '{"en":"Full warranty for the entire subscription period","ru":"Гарантия на весь срок подписки","zh":"整个订阅期内全程保修"}', '{"en":"- An xAI / Grok account","ru":"- Аккаунт xAI / Grok","zh":"- xAI / Grok 账户"}', '{}', 'grok, xai, ai', '{}', '{}', '[]', '[]', 1790161415440, 1790161415440);
