INSERT INTO products (id, slug, category_id, instruction_id, name, short_description, description, thumbnail_url, accent, price, old_price, currency, stock, unlimited_stock, min_quantity, max_quantity, is_active, is_featured, is_popular, sort_priority, delivery_type, delivery_time, static_delivery, warranty, requirements, region_restrictions, tags, seo_title, seo_description, faq, quantity_discounts, created_at, updated_at) VALUES ('prod_steam_card', 'steam-gift-card', 'cat_gaming', 'ins_code', '{"en":"Steam Gift Card","ru":"Подарочная карта Steam","zh":"Steam 礼品卡"}', '{"en":"Top up your Steam Wallet with a digital code.","ru":"Пополнение кошелька Steam цифровым кодом.","zh":"使用数字兑换码为 Steam 钱包充值。"}', '{"en":"A digital code that adds funds to your **Steam Wallet**. Check the region before buying.","ru":"Цифровой код для пополнения **кошелька Steam**. Проверьте регион перед покупкой.","zh":"为 **Steam 钱包**充值的数字兑换码，购买前请确认地区。"}', NULL, '#3a6fd8', 1100, NULL, 'USD', 0, 0, 1, 10, 1, 0, 1, 60, 'inventory', '{"en":"Instantly after payment","ru":"Сразу после оплаты","zh":"付款后立即"}', NULL, '{"en":"Full warranty for the entire subscription period","ru":"Гарантия на весь срок подписки","zh":"整个订阅期内全程保修"}', '{"en":"","ru":"","zh":""}', '{"en":"Global (USD wallets)","ru":"Глобальный (кошельки в USD)","zh":"全球（美元钱包）"}', 'steam, gift card, gaming', '{}', '{}', '[]', '[{"minQuantity":3,"percent":3},{"minQuantity":5,"percent":5}]', 1790161415440, 1790161415440);
